const data = $input.all();
let totalCosecha = 0;
let totalCoste = 0;
let alertasCriticas = 0;
let eficienciaPromedio = 0;
let count = 0;

for (const item of data) {
  const j = item.json || {};
  if (j.peso_total != null) totalCosecha += Number(j.peso_total) || 0;
  if (j.consumo_energia && j.consumo_energia.costo_estimado != null) {
    totalCoste += Number(j.consumo_energia.costo_estimado) || 0;
  }
  if (Array.isArray(j.alertas_legales) && j.alertas_legales.includes('CRITICO')) {
    alertasCriticas += 1;
  }
  if (j.eficiencia_general != null) {
    eficienciaPromedio += Number(j.eficiencia_general) || 0;
    count += 1;
  }
}

const roi =
  totalCoste > 0 && totalCosecha > 0
    ? ((totalCosecha * 3.5 - totalCoste) / totalCoste) * 100
    : 0;
const eficiencia = count > 0 ? eficienciaPromedio / count : 0;

return [
  {
    json: {
      roi: roi.toFixed(2),
      roi_impact: roi > 30 ? 'Excelente' : roi > 15 ? 'Bueno' : 'Mejorable',
      alertas_criticas: alertasCriticas,
      eficiencia_promedio: eficiencia.toFixed(2),
      coste_por_kg: totalCosecha > 0 ? (totalCoste / totalCosecha).toFixed(2) : '0',
      produccion_total_kg: totalCosecha,
      timestamp: new Date().toISOString(),
    },
  },
];
